;(()=>{
  const clean=()=>{
    document.querySelectorAll('a[href*="wa.me"],a[href*="api.whatsapp.com"]').forEach(a=>{
      a.setAttribute('href','mailto:support@parentinghub.pk');
      a.removeAttribute('target');
      const label=(a.textContent||'').trim();
      if(/whatsapp|chat|message/i.test(label)) a.textContent='Email Support';
      a.setAttribute('aria-label','Email Support');
    });
  };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',clean); else clean();
  new MutationObserver(clean).observe(document.documentElement,{subtree:true,childList:true});
})();
